using CustomCodeFramework.Auth.DependencyInjection;using CustomCodeFramework.Mongo.DependencyInjection;using CustomCodeFramework.Redis.DependencyInjection;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Abstractions.Mongo;using Dhole.Content.Infrastructure.Cache;using Dhole.Content.Infrastructure.Mongo;using Microsoft.AspNetCore.Authentication;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;namespace Dhole.Content.Infrastructure.DependencyInjection;
public static class InfrastructureServiceCollectionExtensions
{public static IServiceCollection AddInfrastructure(this IServiceCollection services,IConfiguration configuration){services.AddCustomCodeAuth(configuration);services.PostConfigure<AuthenticationOptions>(o=>{o.DefaultAuthenticateScheme=JwtBearerDefaults.AuthenticationScheme;o.DefaultChallengeScheme=JwtBearerDefaults.AuthenticationScheme;o.DefaultScheme=JwtBearerDefaults.AuthenticationScheme;});services.AddCustomCodeRedis(configuration);services.AddCustomCodeMongo(configuration);services.AddScoped<IContentCacheService,ContentCacheService>();services.AddScoped<IContentChangeSnapshotWriter,ContentChangeSnapshotWriter>();return services;}}
